import os, re, json

def load_grids_from_log():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    # Read the raw jsonl file
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl', 'r').read()

    G = {}

    # Pattern to match demo/test input lines (not JSON-wrapped)
    # Find all text messages
    for m in re.finditer(r'\{"type":"message",[^}]*content:\[{"type":"text","text":"([^"]*)"}\]', t):
        msg_text = m.group(1)
        if 'Demo pair' in msg_text or 'Test input' in msg_text:
            lines = msg_text.split('\n')
            i = 0
            while i < len(lines):
                line = lines[i]
                # Check if this is a header line like "Demo pair 1 input (7x15):"
                header_match = re.match(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\s*', line)
                if header_match:
                    key, h, w = header_match.groups()
                    h, w = int(h), int(w)

                    # Collect next h non-empty lines as grid
                    grid_rows = []
                    j = i + 1
                    while j < len(lines) and len(grid_rows) < h:
                        row_line = lines[j].strip()
                        if row_line and all(c.isdigit() or c == '-' for c in row_line):
                            grid_rows.append([int(x) for x in row_line.split()])
                            j += 1
                        else:
                            j += 1

                    if grid_rows:
                        G[key] = grid_rows
                i += 1

    return G

G = load_grids_from_log()
