import os, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
filepath = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'

# Read all lines
with open(filepath, 'r') as f:
    lines = f.readlines()

G = {}

# Parse each JSON line
for line_num, line in enumerate(lines):
    try:
        msg = json.loads(line.strip())

        # Look for content with thinking or text that mentions grid sizes
        content_text = ""
        if 'thinking' in msg.get('message', {}).get('content', [{}])[0]:
            content_text = msg['message']['content'][0]['thinking']
        elif 'text' in msg.get('message', {}).get('content', [{}])[0]:
            content_text = msg['message']['content'][0].get('text', '')

        if not content_text:
            continue

        # Find all grid headers in this message
        headers = re.findall(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\s*\n', content_text)

        if headers:
            print(f"\n=== Line {line_num}: Found {len(headers)} headers ===")

            for key, h, w in headers:
                h, w = int(h), int(w)

                # Now extract the actual grid rows after this header
                # Find position of this header in content_text
                pattern = r'(Demo pair \d+ (?:input|output)|Test input) \(\d+x\d+\):\s*\n'
                m = re.search(pattern, content_text)
                if m:
                    after_header = content_text[m.end():]

                    # Get next h rows
                    rows = []
                    for row_idx, row_line in enumerate(after_header.split('\n')):
                        row_line = row_line.strip()
                        if row_line and all(c.isdigit() for c in row_line):
                            parts = row_line.split()
                            if len(parts) == w:
                                rows.append([int(x) for x in parts])

                        if len(rows) == h:
                            break

                    if rows:
                        G[key] = rows
                        print(f"{key}: {h}x{w}")
                        print(rows[:3])
                        if len(rows) > 3:
                            print("...")
    except Exception as e:
        pass

print("\n=== Final Grids ===")
for k in sorted(G.keys()):
    print(f"{k}: {len(G[k])}x{len(G[k][0])}")

